"use client"

import { useMemo, useState } from 'react'
import type { ProductDetail } from '@/lib/data/product-detail'
import { formatPrice } from '@/lib/data/product-detail'
import { ProductModal } from './product-modal'
import s from './product-purchase-panel.module.css'

interface ProductPurchasePanelProps {
	product: ProductDetail
}

export function ProductPurchasePanel({ product }: ProductPurchasePanelProps) {
	const [selectedSize, setSelectedSize] = useState<string>()
	const [sizeUnit, setSizeUnit] = useState<'eu' | 'us'>('eu')

	const priceLabel = useMemo(() => formatPrice(product.price, product.currency), [product.price, product.currency])
	const selectedEntry = product.sizes.find((size) => size.eu === selectedSize)

	const formatSizeLabel = (size: { eu: string; us: string }) =>
		sizeUnit === 'eu' ? `EU ${size.eu}` : size.us

	return (
		<div className={s.panel}>
			<div className={s.heading}>
				<p>{product.kicker}</p>
				<h1 className={s.title}>{product.name}</h1>
				<p className={s.price}>{priceLabel}</p>
			</div>

			<p className={s.description}>{product.description}</p>

			<ul className={s.highlights}>
				{product.highlights.map((item) => (
					<li key={item}>{item}</li>
				))}
			</ul>

			<div>
				<div className={s.sectionTitle}>Select size</div>
				<div className={s.sizeToggle} role="group" aria-label="Size units">
					<button type="button" aria-pressed={sizeUnit === 'eu'} onClick={() => setSizeUnit('eu')}>
						EU
					</button>
					<button type="button" aria-pressed={sizeUnit === 'us'} onClick={() => setSizeUnit('us')}>
						US
					</button>
				</div>
				<div className={s.sizeGrid}>
					{product.sizes.map((size) => (
						<button
							key={size.eu}
							type="button"
							className={`${s.sizeButton} ${selectedSize === size.eu ? s.sizeButtonActive : ''}`}
							onClick={() => setSelectedSize(size.eu)}
						>
							{formatSizeLabel(size)}
						</button>
					))}
				</div>
			</div>

			<div className={s.fitCard}>
				<div className={s.sectionTitle}>
					{product.fit.label} · {product.fit.description}
				</div>
				<div className={s.fitBar}>
					<span
						className={s.fitIndicator}
						style={{ left: `${product.fit.value}%` }}
						aria-label={product.fit.description}
					/>
				</div>
			</div>

			<div className={s.ctaBar}>
				<button className={s.primaryButton} type="button">
					{selectedEntry ? `Add ${formatSizeLabel(selectedEntry)}` : 'Add to bag'}
				</button>
				<div className={s.modalRow}>
					<ProductModal title="Materials & Details" triggerLabel="Details" triggerClassName={s.modalTrigger}>
						<ul>
							{product.materials.map((material) => (
								<li key={material}>{material}</li>
							))}
						</ul>
					</ProductModal>
					<ProductModal title="Care Guide" triggerLabel="Care" triggerClassName={s.modalTrigger}>
						<ul>
							{product.careNotes.map((note) => (
								<li key={note}>{note}</li>
							))}
						</ul>
					</ProductModal>
					<ProductModal
						title="Shipping & Returns"
						triggerLabel="Shipping"
						triggerClassName={s.modalTrigger}
					>
						<ul>
							{product.shippingNotes.map((note) => (
								<li key={note}>{note}</li>
							))}
						</ul>
					</ProductModal>
				</div>
			</div>
		</div>
	)
}
